import{_ as a,o as t,c as r,a3 as e}from"./chunks/framework.BWzgKoSO.js";const d=JSON.parse('{"title":"第九部分　怎么判断真假","description":"","frontmatter":{},"headers":[],"relativePath":"ch09-fact-check.md","filePath":"ch09-fact-check.md","lastUpdated":1793331599000}'),o={name:"ch09-fact-check.md"};function n(s,p,c,h,i,l){return t(),r("div",null,[...p[0]||(p[0]=[e('<h1 id="第九部分-怎么判断真假" tabindex="-1">第九部分　怎么判断真假 <a class="header-anchor" href="#第九部分-怎么判断真假" aria-label="Permalink to &quot;第九部分　怎么判断真假&quot;">​</a></h1><p>前面八部分是我核对出来的结果。这一部分讲我怎么核的——包括我核错过的地方。</p><h2 id="_9-1-四个问题" tabindex="-1">9.1　四个问题 <a class="header-anchor" href="#_9-1-四个问题" aria-label="Permalink to &quot;9.1　四个问题&quot;">​</a></h2><p>看到任何一条减肥说法，先问四句。</p><p><strong>第一句：谁说的。</strong></p><p>不是看粉丝多少，是看他是什么身份。医生、注册营养师、有执业资格的教练，和“月瘦二十斤的博主”，说的话分量不一样。但身份也不是免死金牌——有头衔的人照样接广告。</p><p><strong>第二句：原文在哪儿。</strong></p><p>一句话如果找不到最初的出处，它就不算信息，只算转述。转述每过一手都会掉一点条件，掉到最后就剩一句口号。</p><p><strong>第三句：口径是什么。</strong></p><p>减了多少——跟谁比？用多久？去掉安慰剂效应没有？是“平均”还是“最好那个”？</p><p>这一条最要命，也最容易被绕。同一个试验，报 14.9% 和报 11.1%，都不算撒谎，但读者得到的印象差很远。</p><p><strong>第四句：他在卖什么。</strong></p><p>卖课、卖代餐、卖药、卖社群，都可能是诚实的。但你要知道他的收入从哪来，然后决定信几成。</p><h2 id="_9-2-我在这本书里踩过的坑" tabindex="-1">9.2　我在这本书里踩过的坑 <a class="header-anchor" href="#_9-2-我在这本书里踩过的坑" aria-label="Permalink to &quot;9.2　我在这本书里踩过的坑&quot;">​</a></h2><p>摆三个，都是真的，都是我自己查出来的。</p><p><strong>第一个坑：把两份文件的数并成一句。</strong></p><p>原来我那篇文章里写“指南建议每周 150 到 300 分钟运动”，听着没问题。可我去翻原件：食养指南写的是每周 150 到 300 分钟；肥胖症诊疗指南写的是减重期 150 到 420 分钟、维持期 200 到 300 分钟。</p><p>我把两份并成一句，结果就是——读者拿着“150 到 300”去核，在两份文件里都对不上一半。</p><p><strong>第二个坑：算错了一个除法。</strong></p><p>我写过“130 克碳水大概是五碗饭”。这个数是从“一碗饭 26 克碳水”推出来的，但那句话把一碗饭当成了 100 克。</p><p>实际一碗约 200 克熟饭，130 克碳水是 500 克熟饭，两碗半。差了整整一倍。</p><p>这种错最阴——结论方向没错（别断主食），数字翻了一倍，读者一算就发现你不严谨。</p><p><strong>第三个坑：把出处挂错了文件。</strong></p><p>一组供能比（碳水 50% 到 60%、蛋白 15% 到 20%、脂肪 20% 到 30%）我原本写的是《中国居民膳食指南》。后来翻原件，这组数出自《成人肥胖食养指南》正文第 5 页。</p><p>数字是对的，出处是错的。对较真的人来说，出处错了，整段就不算数。</p><p>三个坑有一个共同点：<strong>都不是观点错了，是引用错了。</strong> 观点错了能争，引用错了没得争。</p><h2 id="_9-3-你可以怎么用" tabindex="-1">9.3　你可以怎么用 <a class="header-anchor" href="#_9-3-你可以怎么用" aria-label="Permalink to &quot;9.3　你可以怎么用&quot;">​</a></h2><p>三个动作，任何人都能做。</p><p><strong>一，去翻原件。</strong></p><p>官方指南都是免费的 PDF，卫健委官网能下。论文看摘要就够判断结论，摘要里的“结果”那段和“结论”那段必看。</p><p><strong>二，看样本量。</strong></p><p>十几个人的研究叫“初步发现”，几千人的叫“证据”。同一个结论，前者只能当方向，后者能写进指南。</p><p><strong>三，找相反的说法。</strong></p><p>一条说法如果所有人都在重复，可能因为它对，也可能因为大家都在抄同一篇。搜一句“相反”“不支持”“争议”，看看有没有人反对它、反对得有没有道理。</p><h2 id="_9-4-最后一句" tabindex="-1">9.4　最后一句 <a class="header-anchor" href="#_9-4-最后一句" aria-label="Permalink to &quot;9.4　最后一句&quot;">​</a></h2><p>这一章我不用来证明我严谨。我列的是三个真错，改的过程你都能在修订记录里看到。</p><p>我想说的只有一句：<strong>能核的东西，才值得你信。</strong></p><p>一个人跟你讲得再有道理，你都该有一条退路——去翻原件那条路。这条路上花的十分钟，比在评论区吵十天有用。</p><hr><p>下一部分很短，是我写给你的最后一页。</p>',40)])])}const g=a(o,[["render",n]]);export{d as __pageData,g as default};
